// Module avatars pilote — jeu illustré 26 vignettes (bustes casqués), fourni par
// l'utilisateur (decli_pilots_26). Même architecture que kart-avatar.js : gabarits
// SVG en chaîne, ids suffixés par instance (__SFX__) pour éviter toute collision
// quand plusieurs avatars pilote coexistent sur une page.
//
// Le petit badge rond en haut à droite (numéro de variante) présent dans les fichiers
// fournis a été retiré des 26 gabarits : il faisait doublon avec le numéro de kart
// affiché sur la combinaison et parasitait la lecture aux petites tailles (listes,
// PDF). Le dégradé « badge » associé a été supprimé des <defs> par la même occasion.
//
// Un seul nombre est dynamique :
//  - {{PLATE}} : le numéro sur la combinaison (ex. "08") — dans le fichier fourni
//    ce chiffre est dessiné en vectoriel (pas du texte), donc figé. On le masque
//    avec un cache de la même teinte que la combinaison puis on superpose un vrai
//    <text> avec le numéro de kart réel du pilote, injecté au rendu.

export const PILOT_AVATAR_SCHEME_COUNT = 26;

// Schéma (0-N) déterministe à partir d'un identifiant pilote (id pilote si connu,
// sinon numéro de kart en repli) — même pilote/kart = même avatar à chaque rendu.
export function schemeForPilot(seed) {
  const n = Number(seed);
  if (!Number.isFinite(n)) {
    const str = String(seed == null ? '' : seed);
    let h = 0;
    for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) >>> 0;
    return h % PILOT_AVATAR_SCHEME_COUNT;
  }
  return ((Math.round(n) - 1) % PILOT_AVATAR_SCHEME_COUNT + PILOT_AVATAR_SCHEME_COUNT) % PILOT_AVATAR_SCHEME_COUNT;
}

// Les 26 déclinaisons sont le MÊME dessin vectoriel (703 tracés) décliné en 26
// palettes : squelette et géométrie sont rigoureusement identiques, seules les
// 713 couleurs changent d'une vignette à l'autre. Les stocker en 26 copies
// complètes pesait 2,93 Mo — soit 2,8 Mo de redondance téléchargés par chaque
// visiteur de la page résultats, sur mobile comprise.
//
// On stocke donc : un squelette unique (SKEL, avec un marqueur \u0001 à chaque
// emplacement de couleur), la palette globale des 505 teintes utilisées (PAL), et
// pour chaque déclinaison la liste de ses 713 couleurs sous forme d'index base36
// sur 2 caractères (VARIANTS). Le gabarit complet est reconstitué à la demande
// par template() et mis en cache : une page qui n'affiche que 5 déclinaisons
// n'en matérialise que 5.
//
// La reconstruction est vérifiée à l'octet près contre les 26 fichiers fournis
// (26/26 identiques) : le rendu est rigoureusement inchangé.
